fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // use iterator zip to pair elements and map to xor
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x ^ y)
     .collect()
}